using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using System.Text.RegularExpressions;using System.Web;using System.Web.Script.Serialization;

sealed class Preferences {public string Home="",Theme="Sketchbook",Last="",StartupView="Last note",AfterCapture="Preview and annotate",CaptureFolder="",Typing="Plain text",EditorFont="Segoe UI";public string[] RecentColours=new string[0];public bool FilePreviewEnabled=false;public bool FocusNote=false;public bool TrayClose=true,Top=false,Locked=false,Compact=false,Borderless=true,CaptureButton=false,CaptureNotice=true,Memo=false;public int Width=1060,Height=720,X=-1,Y=-1,Delay=0,Opacity=100;public bool Frame=false,Snap=true;public string CaptureFormat="PNG";public int WidgetOpacity=100;public bool WidgetLocked=false,WidgetTop=true,WidgetSnap=true;public int WidgetX=int.MinValue,WidgetY=int.MinValue;public float EditorSize=12;public int SavePause=1500,UiRevision=0;public bool SpellEnabled=false,HoverMemoTools=true;public string SpellLanguage="",CaptureAction="region";public string NoteKey="Control, Alt, N",RegionKey="Control, Alt, S",WindowKey="Control, Alt, W";public string[] Quick=new[]{"New note","Note view","Task view","Region capture","Captures"};}

sealed class Note {public string Path,Title,Body,Stamp;public override string ToString(){return Title;}}

sealed class Store {

 internal static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=45000000};internal readonly string Config;internal Preferences Pref;internal string RecoveryNotice;internal string Home {get{return Pref.Home;}}internal readonly List<Note> Notes=new List<Note>();internal HashSet<string> Stars=new HashSet<string>();internal Dictionary<string,string> Titles=new Dictionary<string,string>();

 internal Store(string config){Config=System.IO.Path.GetFullPath(config);Directory.CreateDirectory(Config);Pref=ReadPreferences();NormalisePreferences(Pref);if(Pref.UiRevision<4){Pref.Borderless=true;Pref.AfterCapture="Preview and annotate";if(Pref.Quick!=null)Pref.Quick=Pref.Quick.Select(x=>x=="Checklist"?"Task view":x).ToArray();if(Pref.Quick!=null&&!Pref.Quick.Contains("Note view"))Pref.Quick=Pref.Quick.Take(1).Concat(new[]{"Note view"}).Concat(Pref.Quick.Skip(1)).ToArray();Pref.UiRevision=4;}if(String.IsNullOrEmpty(Pref.Home))Pref.Home=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"Jago","Companion");Connect(Pref.Home);}

 internal string PrefsFile {get{return System.IO.Path.Combine(Config,"preferences.json");}}

 internal static void Atomic(string file,string text){Directory.CreateDirectory(System.IO.Path.GetDirectoryName(file));string tmp=file+"."+Guid.NewGuid()+".tmp";File.WriteAllText(tmp,text,new UTF8Encoding(false));if(File.Exists(file)){try{File.Replace(tmp,file,null);}catch{File.Delete(tmp);throw;}}else File.Move(tmp,file);}

 internal static void NormalisePreferences(Preferences p){p.Width=Math.Max(320,Math.Min(10000,p.Width));p.Height=Math.Max(240,Math.Min(10000,p.Height));p.Opacity=Math.Max(30,Math.Min(100,p.Opacity));p.WidgetOpacity=Math.Max(30,Math.Min(100,p.WidgetOpacity));p.EditorSize=Single.IsNaN(p.EditorSize)||Single.IsInfinity(p.EditorSize)?12:Math.Max(6,Math.Min(72,p.EditorSize));p.SavePause=Math.Max(250,Math.Min(10000,p.SavePause));if(String.IsNullOrWhiteSpace(p.EditorFont))p.EditorFont="Segoe UI";if(String.IsNullOrWhiteSpace(p.Home))p.Home="";p.Quick=p.Quick==null?new Preferences().Quick:p.Quick.Where(x=>!String.IsNullOrWhiteSpace(x)).Take(24).ToArray();}
 internal Preferences ReadPreferences(){foreach(string path in new[]{PrefsFile,PrefsFile+".backup"}){if(!File.Exists(path))continue;try{if(new FileInfo(path).Length>1000000)throw new InvalidDataException("Preferences exceed the supported size.");var value=Json.Deserialize<Preferences>(File.ReadAllText(path));if(value==null)throw new InvalidDataException("Empty preferences.");if(path!=PrefsFile)RecoveryNotice="Preferences were recovered from the last good backup. Your notes and captures are unchanged.";return value;}catch{if(path==PrefsFile){try{File.Copy(path,path+".damaged-"+Guid.NewGuid().ToString("N"));}catch{}RecoveryNotice="Preferences could not be read. Defaults were loaded; your notes and captures are unchanged. Choose your existing Companion home in Settings if needed.";}}}return new Preferences();}
 internal void SavePrefs(){if(File.Exists(PrefsFile))try{string previous=File.ReadAllText(PrefsFile);if(previous.Length<=1000000&&Json.Deserialize<Preferences>(previous)!=null)Atomic(PrefsFile+".backup",previous);}catch{}Atomic(PrefsFile,Json.Serialize(Pref));}

 internal void Connect(string home){home=System.IO.Path.GetFullPath(home);Directory.CreateDirectory(home);foreach(string n in new[]{"Notes","Captures","Attachments","Templates",".jago"})Directory.CreateDirectory(System.IO.Path.Combine(home,n));Pref.Home=home;try{string titles=System.IO.Path.Combine(home,".jago","page-titles.json");Titles=File.Exists(titles)?Json.Deserialize<Dictionary<string,string>>(File.ReadAllText(titles)):new Dictionary<string,string>();}catch{Titles=new Dictionary<string,string>();}Stars=File.Exists(System.IO.Path.Combine(home,".jago","stars.json"))?new HashSet<string>(Json.Deserialize<string[]>(File.ReadAllText(System.IO.Path.Combine(home,".jago","stars.json")))):new HashSet<string>();Reload();SavePrefs();}

 internal string Relative(string path){string full=System.IO.Path.GetFullPath(path),root=Home.TrimEnd('\\')+"\\";if(!full.StartsWith(root,StringComparison.OrdinalIgnoreCase))throw new Exception("Choose a file inside your Companion home.");return full.Substring(root.Length).Replace('\\','/');}

 internal string Resolve(string relative){return Checked(System.IO.Path.Combine(Home,relative.Replace('/',System.IO.Path.DirectorySeparatorChar)));}

 internal string Checked(string path){Relative(path);string at=System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(path));while(at!=null&&at.Length>=Home.Length){if(Directory.Exists(at)&&(File.GetAttributes(at)&FileAttributes.ReparsePoint)!=0)throw new Exception("Choose a regular folder, not a junction or linked directory.");if(at.Equals(Home,StringComparison.OrdinalIgnoreCase))break;at=System.IO.Path.GetDirectoryName(at);}return System.IO.Path.GetFullPath(path);}

 internal void Reload(){Notes.Clear();int total=0;Scan(System.IO.Path.Combine(Home,"Notes"),0,ref total);}

 void Scan(string dir,int depth,ref int total){if(depth>8||Notes.Count>=5000||(File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)return;foreach(string f in Directory.GetFiles(dir,"*.md").OrderBy(x=>x)){var info=new FileInfo(f);if(info.Length>262144||total+info.Length>32000000)continue;string body=File.ReadAllText(f);total+=body.Length;var n=new Note{Path=f,Body=body,Stamp=body};n.Title=TitleFor(n,body);Notes.Add(n);if(Notes.Count>=5000)break;}foreach(string d in Directory.GetDirectories(dir))Scan(d,depth+1,ref total);}

 internal static string Title(string body,string fallback){string first=body.Split('\n').FirstOrDefault(x=>!String.IsNullOrWhiteSpace(x));return String.IsNullOrEmpty(first)?fallback:first.Trim().TrimStart('#',' ').Substring(0,Math.Min(100,first.Trim().TrimStart('#',' ').Length));}

 internal static string Clean(string s){s=Regex.Replace(s??"",@"[<>:""/\\|?*\x00-\x1f]","-").Trim().Trim('.');return String.IsNullOrEmpty(s)?"Untitled":s.Substring(0,Math.Min(80,s.Length));}

 internal Note Create(string title,string body,string folder=""){string dir=System.IO.Path.Combine(Home,"Notes");foreach(string part in folder.Split(new[]{'/','\\'},StringSplitOptions.RemoveEmptyEntries))dir=System.IO.Path.Combine(dir,Clean(part));Checked(System.IO.Path.Combine(dir,"test.md"));Directory.CreateDirectory(dir);string f=System.IO.Path.Combine(dir,Clean(title)+"-"+Guid.NewGuid().ToString("N").Substring(0,8)+".md");Atomic(f,body);var n=new Note{Path=f,Title=Title(body,title),Body=body,Stamp=body};Notes.Add(n);if(title=="Task list")SetTitle(n,title);return n;}

 internal void Save(Note n,string body){if(body.Length>262144)throw new Exception("This note is over 256 KB. Split it into smaller notes.");Checked(n.Path);if(File.Exists(n.Path)&&File.ReadAllText(n.Path)!=n.Stamp){string conflict=System.IO.Path.Combine(Home,"Notes","Recovered edit-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6)+".md");Atomic(conflict,body);n.Path=conflict;n.Body=n.Stamp=body;n.Title=Title(body,"Recovered edit");throw new Exception("This note changed outside Companion. Your edit was saved as a recovered note; reload to review both.");}string old=File.Exists(n.Path)?File.ReadAllText(n.Path):null;if(old!=null)Atomic(System.IO.Path.Combine(Home,".jago",System.IO.Path.GetFileName(n.Path)+".previous"),old);Atomic(n.Path,body);n.Body=n.Stamp=body;n.Title=TitleFor(n,body);}

 internal string Trash(Note n){Checked(n.Path);string d=System.IO.Path.Combine(Home,".jago","Trash");Directory.CreateDirectory(d);string target=System.IO.Path.Combine(d,Guid.NewGuid()+"-"+System.IO.Path.GetFileName(n.Path));File.Move(n.Path,target);Notes.Remove(n);return target;}

 internal string TitleFor(Note n,string body){string title;if(n!=null&&Titles.TryGetValue(Relative(n.Path),out title))return title;return Title(body,n==null?"Untitled":System.Text.RegularExpressions.Regex.Replace(System.IO.Path.GetFileNameWithoutExtension(n.Path),@"-[a-f0-9]{8}$",""));}
 internal void SetTitle(Note n,string title){Titles[Relative(n.Path)]=title.Trim();n.Title=title.Trim();Atomic(System.IO.Path.Combine(Home,".jago","page-titles.json"),Json.Serialize(Titles));}
 internal void Star(Note n){string key=Relative(n.Path);if(!Stars.Remove(key))Stars.Add(key);Atomic(System.IO.Path.Combine(Home,".jago","stars.json"),Json.Serialize(Stars.ToArray()));}

 internal string Attach(string file){if(!File.Exists(file))throw new Exception("That file is unavailable.");if(new FileInfo(file).Length>50000000)throw new Exception("Choose an attachment under 50 MB.");string target=System.IO.Path.Combine(Home,"Attachments",Guid.NewGuid().ToString("N").Substring(0,8)+"-"+Clean(System.IO.Path.GetFileName(file)));File.Copy(file,target);return target;}

 internal string AttachmentLink(Note n,string file){var from=new Uri(System.IO.Path.GetDirectoryName(n.Path)+"\\");string relative=Uri.UnescapeDataString(from.MakeRelativeUri(new Uri(file)).ToString()).Replace('\\','/');return (new[]{".png",".jpg",".jpeg",".webp",".gif"}.Contains(System.IO.Path.GetExtension(file).ToLowerInvariant())?"!":"")+"["+System.IO.Path.GetFileName(file).Replace("]","")+ "]("+Uri.EscapeUriString(relative)+")";}

 internal static string Html(string s){return HttpUtility.HtmlEncode(s??"");}

 internal static string Inline(string s,string folder=null){var fragments=new List<string>();string input=Regex.Replace(s,@"(!?)\[([^\]]*)\]\(([^)]+)\)",m=>{string href=Uri.UnescapeDataString(m.Groups[3].Value),label=Html(m.Groups[2].Value);bool image=m.Groups[1].Value=="!";string fragment=null;if(image&&folder!=null){try{string root=System.IO.Path.GetFullPath(folder);while(System.IO.Path.GetFileName(root)!="Notes"&&System.IO.Directory.GetParent(root)!=null)root=System.IO.Directory.GetParent(root).FullName;if(System.IO.Path.GetFileName(root)=="Notes")root=System.IO.Directory.GetParent(root).FullName;string target=System.IO.Path.GetFullPath(System.IO.Path.Combine(folder,href.Replace('/',System.IO.Path.DirectorySeparatorChar)));if(target.StartsWith(root.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase)&&File.Exists(target)&&new[]{".png",".jpg",".jpeg",".gif",".webp"}.Contains(System.IO.Path.GetExtension(target).ToLowerInvariant()))fragment="<img style='max-width:100%;height:auto' alt='"+label+"' src='"+Html(new Uri(target).AbsoluteUri)+"'>";}catch{}}else if(!image&&(href.StartsWith("https://",StringComparison.OrdinalIgnoreCase)||href.StartsWith("http://",StringComparison.OrdinalIgnoreCase)||href.StartsWith("mailto:",StringComparison.OrdinalIgnoreCase))&&Uri.IsWellFormedUriString(href,UriKind.Absolute))fragment="<a rel='noopener noreferrer' href='"+Html(href)+"'>"+label+"</a>";if(fragment==null)return m.Value;fragments.Add(fragment);return "JAGOFRAGMENT"+(fragments.Count-1)+"END";});string t=Html(input);t=Regex.Replace(t,@"`([^`]+)`","<code>$1</code>");t=Regex.Replace(t,@"\*\*([^*]+)\*\*","<strong>$1</strong>");t=Regex.Replace(t,@"(?<!\*)\*([^*]+)\*(?!\*)","<em>$1</em>");for(int i=0;i<fragments.Count;i++)t=t.Replace("JAGOFRAGMENT"+i+"END",fragments[i]);return t;}
 internal static string Markdown(string body,string folder=null){var b=new StringBuilder();bool code=false,table=false;foreach(string line in body.Replace("\r","").Split('\n')){if(line.StartsWith("```")){if(table){b.Append("</table>");table=false;}b.Append(code?"</code></pre>":"<pre><code>");code=!code;continue;}if(code){b.Append(Html(line)+"\n");continue;}if(line.StartsWith("|")&&line.EndsWith("|")){if(Regex.IsMatch(line,@"^\|[\s:|\-]+\|$"))continue;if(!table){b.Append("<table>");table=true;}b.Append("<tr>"+String.Join("",line.Trim('|').Split('|').Select(cell=>"<td>"+Inline(cell.Trim(),folder)+"</td>"))+"</tr>");continue;}if(table){b.Append("</table>");table=false;}var h=Regex.Match(line,@"^(#{1,6})\s+(.*)$");if(h.Success){int n=h.Groups[1].Value.Length;b.Append("<h"+n+">"+Inline(h.Groups[2].Value,folder)+"</h"+n+">");}else if(Regex.IsMatch(line,@"^\s*- \[[ xX]\] ")){bool done=Regex.IsMatch(line,@"^\s*- \[[xX]\]");b.Append("<p class='task'>"+(done?"☑ ":"☐ ")+Inline(Regex.Replace(line,@"^\s*- \[[ xX]\] ",""),folder)+"</p>");}else if(line.StartsWith("- "))b.Append("<p>• "+Inline(line.Substring(2),folder)+"</p>");else b.Append("<p>"+Inline(line,folder)+"</p>");}if(code)b.Append("</code></pre>");if(table)b.Append("</table>");return "<!doctype html><html><head><meta charset='utf-8'><meta http-equiv='Content-Security-Policy' content=\"default-src 'none'; img-src file: data:; style-src 'unsafe-inline'\"><title>Note preview</title><style>body{font:18px/1.6 system-ui;color:#27363a;background:#f8f6f0;max-width:800px;margin:40px auto;padding:24px}pre,code{background:#e9e5dd}pre{padding:16px;white-space:pre-wrap}p{min-height:.5em}h1{line-height:1.2}a{color:#486d6e}table{border-collapse:collapse;width:100%}td{border:1px solid #bcb8aa;padding:8px 12px}</style></head><body>"+b+"</body></html>";}
 internal static string Signature(string name,string role,string email,string phone,string web,string logo,string color){if(!Regex.IsMatch(color??"",@"^#[0-9a-fA-F]{6}$"))color="#486d6e";string image=Uri.IsWellFormedUriString(logo,UriKind.Absolute)&&logo.StartsWith("https://",StringComparison.OrdinalIgnoreCase)?"<td style='padding-right:16px'><img src='"+Html(logo)+"' alt='' width='80' style='display:block;width:80px;height:auto'></td>":"";string website=Uri.IsWellFormedUriString(web,UriKind.Absolute)&&web.StartsWith("https://",StringComparison.OrdinalIgnoreCase)?"<br><a style='color:"+color+"' href='"+Html(web)+"'>"+Html(web)+"</a>":"";return "<table cellpadding='0' cellspacing='0' role='presentation' style='font:14px Arial,sans-serif;color:#27363a'><tr>"+image+"<td style='border-left:3px solid "+color+";padding-left:16px'><strong style='font-size:18px;color:"+color+"'>"+Html(name)+"</strong><br>"+Html(role)+"<br><a style='color:"+color+"' href='mailto:"+Html(email)+"'>"+Html(email)+"</a><br>"+Html(phone)+website+"</td></tr></table>";}

}
